import axios from 'axios';

const SYSTEM = `Eres el motor de scoring de dealflow para Latin Leap, fondo de USD 20M enfocado en startups pre-seed y seed de LATAM hispanohablante.

Responde SOLO con JSON sin markdown:
{"geography":0,"sector":0,"traction":0,"market_size":0,"team":0,"stage":"Pre-seed","capital":"USD XK","country":"XX","verdict":""}

Scores 1-10:
- geography: 10 = opera en LATAM hispanohablante
- sector: 10 = tech con alto potencial en LATAM  
- traction: 10 = traccion clara y medible
- market_size: 10 = mercado enorme y validado
- team: 10 = founders excepcionales con track record
- verdict: STRONG FIT / WATCH / PASS`;

export default defineComponent({
  props: {
    anthropic_api_key: { type: 'string', secret: true, label: 'Anthropic API Key' }
  },
  async run({ steps, $ }) {
    const startups = steps.merge_sources.$return_value || [];
    const scored = [];

    for (const s of startups) {
      try {
        const res = await axios.post(
          'https://api.anthropic.com/v1/messages',
          {
            model: 'claude-haiku-4-5-20251001',
            max_tokens: 300,
            system: SYSTEM,
            messages: [{ role: 'user', content: `Analiza: ${s.company} - ${s.desc} - País: ${s.country}` }]
          },
          { headers: { 'x-api-key': this.anthropic_api_key, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' } }
        );
        const txt = res.data.content[0].text.replace(/```json|```/g, '').trim();
        const scores = JSON.parse(txt);
        const total = Math.round(
          scores.geography * 0.20 * 10 +
          scores.sector     * 0.20 * 10 +
          scores.traction   * 0.25 * 10 +
          scores.market_size* 0.20 * 10 +
          scores.team       * 0.15 * 10
        );
        scored.push({ ...s, scores, total, verdict: scores.verdict });
        await new Promise(r => setTimeout(r, 500));
      } catch (e) {
        console.log(`Error scoring ${s.company}:`, e.message);
      }
    }

    console.log(`Scored ${scored.length} startups`);
    return scored;
  }
});

export default defineComponent({
  async run({ steps, $ }) {
    const THRESHOLD = 65;
    const scored = steps.score_with_claude.$return_value || [];
    const qualified = scored.filter(s => s.total >= THRESHOLD)
      .sort((a, b) => b.total - a.total);
    console.log(`${qualified.length} startups above threshold ${THRESHOLD}`);
    return { qualified, threshold: THRESHOLD, total_analyzed: scored.length };
  }
});

import axios from 'axios';

export default defineComponent({
  props: {
    telegram_bot_token: { type: 'string', secret: true, label: 'Telegram Bot Token' },
    telegram_chat_id:   { type: 'string', label: 'Telegram Chat ID' }
  },
  async run({ steps, $ }) {
    const token = this.telegram_bot_token;
    const chat  = this.telegram_chat_id;
    const { qualified, threshold, total_analyzed } = steps.filter_by_threshold.$return_value;
    const fecha = new Date().toLocaleDateString('es-CO', { weekday:'long', day:'numeric', month:'long' });

    const send = async (text) => {
      await axios.post(`https://api.telegram.org/bot${token}/sendMessage`, {
        chat_id: chat, text, parse_mode: 'Markdown'
      });
      await new Promise(r => setTimeout(r, 400));
    };

    const bar = n => {
      const filled = Math.round(n / 2);
      return '█'.repeat(filled) + '░'.repeat(5 - filled) + ' ' + n + '/10';
    };

    const verdict = t => t >= 75 ? { t: 'STRONG FIT', e: '🟢' } : t >= 60 ? { t: 'WATCH', e: '🟡' } : { t: 'PASS', e: '🔴' };

    const FLAGS = { MX:'🇲🇽', CO:'🇨🇴', CL:'🇨🇱', AR:'🇦🇷', PE:'🇵🇪', BR:'🇧🇷', EC:'🇪🇨', UY:'🇺🇾' };

    const SECTORS = {
      fintech:    ['pago','financi','crédito','banco','neobank','inversión','seguro','impuesto','nómina','tarjeta','bnpl','open banking','token','remesa','factura','conciliaci','scoring','billetera'],
      healthtech: ['salud','médic','telemedicin','farmacia','clínica','cuidado','mental','odontol','ortodoncia'],
      proptech:   ['casa','inmueble','apart','arriendo','renta','propiedad','vivienda'],
      logistics:  ['logístic','carga','envío','transporte','delivery','última milla','freight'],
      agritech:   ['agro','ganadería','cosecha','agrícola','campo','climático','paramétrico'],
      'hr & work':['rrhh','nómina','empleado','talento','recursos humanos','beneficio','asistencia'],
      edtech:     ['educaci','inglés','aprendizaje','learning','universitari','tutor'],
      legaltech:  ['legal','contrato','trámite','jurídico','vehicular'],
      'b2b saas': ['software','saas','api','gestión','automatiz','erp','analytics','no-code','crm','pos','facturación','verificaci'],
      commerce:   ['marketplace','ecommerce','retail','vendedor','tienda','moda','belleza','marca','social commerce','restaurante','loyalty','lealtad','mueble','turismo'],
    };
    const getSector = desc => {
      const d = (desc||'').toLowerCase();
      for (const [sec, kws] of Object.entries(SECTORS)) {
        if (kws.some(k => d.includes(k))) return sec.charAt(0).toUpperCase() + sec.slice(1);
      }
      return 'Otro';
    };

    const buildBullets = s => {
      const b = [];
      if (s.scores.geography >= 8)   b.push('Opera en mercados core de LATAM hispanohablante con alta densidad de oportunidad');
      if (s.scores.traction >= 7)    b.push('Señales de tracción tempranas validadas: adopción, revenue o usuarios activos');
      if (s.scores.market_size >= 8) b.push('Mercado total direccionable grande con múltiples verticales de expansión');
      if (s.scores.team >= 8)        b.push('Equipo fundador con experiencia relevante y track record en el sector');
      if (s.scores.sector >= 8)      b.push('Sector con alto potencial de crecimiento y defensibilidad en LATAM');
      if (b.length < 3)              b.push('Perfil de riesgo consistente con tesis early-stage de Latin Leap');
      return b.slice(0, 3);
    };

    const buildMessage = s => {
      const t  = s.total;
      const v  = verdict(t);
      const fl = FLAGS[s.country] || '🌎';
      const sc = getSector(s.desc);
      const bullets = buildBullets(s);
      return [
        `${v.e} *${s.company}* — ${v.t}`,
        ``,
        `${s.desc}`,
        ``,
        `📋 *Ficha*`,
        `${fl} País: ${s.country}   🏷 Sector: ${sc}`,
        `📌 Stage: ${s.stage}   💰 Capital: ${s.capital}`,
        `🔗 Fuente: ${s.source}`,
        s.website ? `🌐 ${s.website}` : null,
        ``,
        `💡 *Por qué llama la atención*`,
        ...bullets.map(b => `• ${b}`),
        ``,
        `📊 *Scorecard — ${t}/100*`,
        `🗺 Geografía   ${bar(s.scores.geography)}`,
        `⚙️ Sector       ${bar(s.scores.sector)}`,
        `📈 Traction     ${bar(s.scores.traction)}`,
        `🏦 Market Size  ${bar(s.scores.market_size)}`,
        `👥 Team         ${bar(s.scores.team)}`,
      ].filter(Boolean).join('\n');
    };

    if (qualified.length === 0) {
      await send(`🔍 *Latin Leap Dealflow*\n${fecha}\n\nSe analizaron *${total_analyzed}* startups esta semana. Ninguna superó el umbral mínimo de ${threshold}/100. El pipeline sigue activo para el próximo ciclo.`);
      return { sent: 0 };
    }

    const strongFit = qualified.filter(s => s.total >= 75);
    const watch     = qualified.filter(s => s.total >= 60 && s.total < 75);

    const intro = [
      `🚀 *Latin Leap Dealflow — ${fecha}*`,
      ``,
      `Esta semana el scanner analizó *${total_analyzed} startups* del ecosistema LATAM y encontró *${qualified.length} oportunidades* que superan el umbral de ${threshold}/100.`,
      strongFit.length > 0 ? `Se identificaron *${strongFit.length} STRONG FIT* listas para primera reunión` + (watch.length > 0 ? ` y *${watch.length} en radar* para seguimiento.` : '.') : `Se identificaron *${watch.length} oportunidades WATCH* para seguimiento cercano.`,
      ``,
      `A continuación el detalle de cada deal:`,
    ].join('\n');

    await send(intro);

    for (const s of qualified) {
      await send(buildMessage(s));
    }

    return { sent: qualified.length };
  }
});
